INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(14800, 0, 148, 0, 0, 0, 'Darkshore', 'Darkshore is a long strip of coast on the northwestern edge of Kalimdor, a cold and misty country of grey beaches, rocky bluffs and dark evergreen woods pressed against the mountains to the east. Ten thousand years ago it was a rich land of the kaldorei empire, and Queen Azshara''s Highborne dwelt in the twin towns of Ameth''Aran and Bashal''Aran, and the city of Mathystra shone in the north. The Sundering left them in ruins, and their restless dead still walk among the stones. Today the night elves hold only the port of Auberdine, and the land around it is sickening. Fel moss spreads through the woods, a taint from Felwood fouls the Cliffspring River, a plague has turned the thistle bears rabid, the deer are sickly, the moonkin grow hostile and the Blackwood furbolgs are openly hostile. Stormscale naga haunt the northern ruins, Greymist murlocs raid the shore, the Twilight''s Hammer camps at the Master''s Glaive and a warlock cult has gathered at the Tower of Althalaxx. In the remote far northeast, the Shatterspear trolls keep to themselves.', 'warcraft.wiki.gg/wiki/Darkshore_(Classic) (long coast, cold and foggy, mountains east, former kaldorei wealth, Ameth''Aran and Bashal''Aran, Sundering, Auberdine only town, taint from Felwood); warcraft.wiki.gg/wiki/Ruins_of_Mathystra (night elf city destroyed with the Well); quest 985 reward text and Terenthis gossip npc_text 3334 (fel moss); quest 4762 reward text (Felwood source); quest 2118 description (rabid thistle bears); creature 12298 Sickly Deer spawns; quest 4811 description (hostile moonkin); quest 984/985 (corrupt Blackwood furbolgs); quest 944 description (naga and Twilight''s Hammer); quest 966 and page_text 361 (warlock cult at Althalaxx); warcraft.wiki.gg/wiki/Shatterspear_tribe (pre-Cataclysm: reclusive village at the northeast edge); DB: Shatterspear Troll 10919 spawns at map 68,21; quest 2118 description (a sickness spreads, thistle bears rabid); quest 949 (Twilight''s Hammer camp at the Glaive)'),
(14801, 1, 148, 1, 0, 0, 'Auberdine', 'Auberdine is the only night elf town on the Darkshore coast, a port of low, arched timber halls among the pines, lit by lamps and guarded by Sentinels. Elder Thundris Windweaver sees to its affairs beside a village council, while Sentinels Glynda Nal''Shea and Elissa Starbreeze see to its defense. Trade has drawn others: dwarves of the Stonehammer and Steelhand families teach mining and smithing and sell their wares, and a gnome tinkers near the inn. Three docks serve the town. From the northern pier the Moonspray sails for Rut''theran Village, from the southern the Bravery crosses to Stormwind Harbor, and from the western pier Elune''s Blessing carries travelers to Azuremyst Isle. A moonwell and a lighthouse stand nearby.', 'warcraft.wiki.gg/wiki/Auberdine (pre-Cataclysm: only stronghold, low arched wooden buildings among pines, lamp-lit streets, lighthouse, dwarven smithy, village council, Sentinels); npc_text 5480 (Thamarian dock gossip: northern dock to Rut''theran, southern to Stormwind Harbor, western pier to Azuremyst); transports guid 2 (176310 The Bravery, Auberdine to Stormwind Harbor), 3 (176244 The Moonspray, Rut''theran), 9 (181646 Elune''s Blessing, Valaar''s Berth); quest 4761 description (Thundris elder); quest 4740 (Auberdine Village Council, Glynda); quest 965 description (Elissa''s charge); DB spawns in area 442: Kurdram and Thelgrum Stonehammer, Elisa and Gorbold Steelhand, Delfrum Flintbeard, Wizbang Cranktoggle beside Innkeeper Shaussiy, Gwennyth Bly''Leggonde; npc_text 5943 (Gwennyth, Temple of the Moon); quests 4763, 4812 (Auberdine moonwell)'),
(14802, 1, 148, 2, 0, 0, 'Mist''s Edge', 'North of Auberdine, Mist''s Edge is the longest stretch of Darkshore''s coast, a run of gloomy bays and grey beaches where crabs scuttle over the sand and Greymist murlocs keep their camps. The waters are worse. Threshers and coastal frenzies hunt offshore, and two ships, the Silver Dawning and the Mist Veil, lie on the seabed north of the town, sunk with their captains when murlocs fell on them as they sailed in. Their logs still rest below in lockboxes. Farther north, a shipwrecked self-styled pirate, Captain Gelkak Gyromast, curses the threshadons that sank his ship and wants his mechanical first mate, the Threshwackonator 4100, put back in working order.', 'warcraft.wiki.gg/wiki/Mist''s_Edge (longest coastline, gloomy bays, grey beaches, murlocs, crabs; Cataclysm cultist camp ignored); quest 982 description (Silver Dawning and Mist Veil wrecked by murlocs); quest 1141 description (no boats since the murlocs); quests 2098, 2078 (Gelkak, threshadons, Threshwackonator); DB area 452: Greymist murlocs, Darkshore Threshers, Coastal Frenzy, crawlers, Gelkak 6667, Threshwackonator 6669, both lockboxes'),
(14803, 1, 148, 3, 0, 0, 'Cliffspring River', 'The Cliffspring River runs down from the eastern mountains to empty into the sea at Mist''s Edge, north of Auberdine. Its waters were once pure, but they have begun to turn foul, and Thundris Windweaver fears the wash will soon reach the town. A sample drawn from the pool beneath the first waterfall upriver, where a bridge crosses overhead, proved putrid, and Thundris traces the taint east to Felwood. Along the banks stands the northern camp of the Blackwood furbolgs, its stores of fruit, nuts and grain heaped near a bonfire by the water, with warriors and totemics of the tribe keeping watch.', 'quest 4762 description and reward text; quest 4763 objectives (northern camp, bonfire closest to the river); DB area 456: Blackwood Warrior, Blackwood Totemic, Blackwood Nut/Fruit Stores; Grain Stores just outside in plain 148; warcraft.wiki.gg/wiki/Cliffspring_Falls (source of the river, once pure)'),
(14804, 1, 148, 4, 0, 0, 'Cliffspring Falls', 'Cliffspring Falls spills from the mountains east and a little north of Auberdine, the source of the Cliffspring River. Behind the falling water lies a cave where rare mushrooms grow, scaber stalks and death caps that Barithras Moonshade needs for a potion. The Ancients of the Grove warned him to stay away, sensing that the cave hid a new evil in Darkshore, and their fears were well founded. Stormscale naga, wave riders and sirens, have made the cavern their lair, among them one known as Lord Sinslayer, and thugs of the Twilight''s Hammer have been seen in their company.', 'quest 947 description (cave behind Cliffspring Falls, mushrooms, Ancients'' warning); quest 948 description; warcraft.wiki.gg/wiki/Cliffspring_Falls (source of the Cliffspring River; naga and Twilight''s Hammer in the caves); DB: Stormscale Wave Rider/Siren, Lord Sinslayer 7017 and four Twilight Thugs 2339 at x 6760-6900, y -640..-790 (cave behind the falls); Scaber Stalk spawns in 445'),
(14805, 1, 148, 5, 0, 0, 'Bashal''Aran', 'Bashal''Aran was one of the twin towns Queen Azshara gave to her Highborne, ruled with Ameth''Aran by Athrikus Narassin and home to his second, the mage Asterion. Both towns fell when the Well of Eternity was destroyed. Its broken stones east of Auberdine are now overrun by vile sprites, wild grells and Deth''ryll satyrs, minions of the demons who feed on the magic lingering in the ruins and grow stronger for it. There is one shrine they will not approach. On a small bluff on the western side, a strange blue aura hangs between the pillars, and within it the spectral Asterion has been held prisoner for more than a thousand years.', 'page_text 364, 365 (The Lay of Ameth''Aran: twin towns, Athrikus governor, Asterion his second living in Bashal''Aran); warcraft.wiki.gg/wiki/Bashal''Aran (destroyed with the Well); quest 954 description (demonic minions feed on the magic, shrine with blue aura on the western bluff); quest 956 completion text (a thousand years and more); DB area 446: Vile Sprite, Wild Grell, Deth''ryll Satyr, Asterion 3650'),
(14806, 1, 148, 6, 0, 0, 'Tower of Althalaxx', 'The Tower of Althalaxx rises in the north of Darkshore, northeast of Auberdine, some way removed from the twin towns it once watched over. Athrikus Narassin, Azshara''s governor of Ameth''Aran and Bashal''Aran, spent most of his days here rather than among the people he ruled. Ten thousand years later the tower is occupied again. Warlocks calling themselves the Cult of the Dark Strand have gathered around and inside it, fanatics and voidcallers with a satyr, Delmanis the Hated, among them, while the most powerful keep to the upper rooms. From hiding in the nearby woods, Balthule Shadowstrike watches the cult and sends word of it to Auberdine and to his master in Ashenvale.', 'page_text 364 (Athrikus spent most of his days in his Tower of Althalaxx, removed from the towns); quest 965 description (northeast of Auberdine); quest 966 description and page_text 361 (warlocks around and inside the tower, satyr, Cult of the Dark Strand); quest 1143 description (more powerful warlocks at the top); DB area 444: Dark Strand Fanatic, Dark Strand Voidcaller, Athrikus Narassin 3660, Delmanis the Hated 3662; Balthule 3661 just outside in plain 148'),
(14807, 1, 148, 7, 0, 0, 'Ruins of Mathystra', 'At the northern end of Darkshore lie the Ruins of Mathystra, once a great bastion of the night elves. The city was shattered when the Well of Eternity was destroyed, and its survivors left for smaller villages along the coast to the south. Its glory has faded, but shards of its magic remain in the relics and small cat figurines scattered among the grass and broken stones. The Stormscale naga hold the ruins now, myrmidons, sorceresses and warriors guarding them fiercely, and a naga called Lady Vespira among them. Onu of the Grove of the Ancients wants the relics studied, fearing that the Twilight''s Hammer means to turn this old elven magic to its own ends.', 'warcraft.wiki.gg/wiki/Ruins_of_Mathystra (night elf city destroyed with the Well, survivors moved to smaller coastal villages, Stormscale naga guard it); quest 951 description and reward text (relics, once great bastion, shards of magic remain); DB area 443: Stormscale Myrmidon/Sorceress/Warrior, Lady Vespira 7016, Mathystra Relic and Cat Figurine objects'),
(14808, 1, 148, 8, 0, 0, 'The Long Wash', 'The Long Wash is the shortest stretch of Darkshore''s coast, running south from Auberdine, a gloomy shore strewn with debris and the carcasses of sea creatures. Great beasts of the sea have been beaching themselves here in growing numbers, and the skeleton of a sea turtle lies in the water west of the town beside a sunken ship. Greymist murlocs and crawlers pick over the sand. In the shallows lie crates of elunite ore, spilled long ago when a ship broke on the rocks near the Auberdine lighthouse, still guarded by the cursed Shade of Elura.', 'warcraft.wiki.gg/wiki/The_Long_Wash (shortest coastline, south from Auberdine, debris and dead sea creatures, murlocs); quests 3524, 4681 descriptions (beached creatures, sea turtle west of Auberdine near a sunken vessel); DB area 453: Crate of Elunite x7, Shade of Elura 6133, Skeletal Sea Turtle 176189, Greymist Coastrunner, Pygmy Tide Crawler; Darnassus entry 165720 Elanaria''s Trial (quest 1683 wreck near the Auberdine lighthouse)'),
(14809, 1, 148, 9, 0, 0, 'Ameth''Aran', 'Ameth''Aran lies east of the road south of Auberdine, twin to Bashal''Aran and once a town where Azshara''s Highborne practiced their powerful magic freely. When the Well of Eternity was destroyed it fell to ruin, and its people did not rest. Cursed, writhing and wailing Highborne spirits still drift among the broken walls, wielding the magical implements they used in life, and one called Lady Moongazer walks among them. Two great tablets here tell of the town and its fall. In the ruins still burns an ancient blue flame, a fire in which Asterion''s moonstone seal can be destroyed, and somewhere among the restless dead wanders the spirit of Anaya Dawnrunner.', 'quest 953 description (servants of Azshara practiced their magics, restless Highborne spirits, two tablets); quest 958 description (east of the road, spirits wield magical implements); quest 957 description (ancient blue flame in Ameth''Aran, twin of Bashal''Aran); quest 963 description (Anaya); DB area 447: Cursed/Writhing/Wailing Highborne, Lady Moongazer 2184, Anaya Dawnrunner 3667, The Lay/Fall of Ameth''Aran tablets, Ancient Flame 16393'),
(14810, 1, 148, 10, 0, 0, 'Twilight Vale', 'Twilight Vale is the southern forest of Darkshore, stretching from below Ameth''Aran toward the Ashenvale border, its woods cut by the Wildbend River. Travelers do best to keep to the road. Rabid and grizzled thistle bears, moonstalkers and foreststriders roam beneath the trees, many of the deer are sick, and the Blackwood furbolgs, once friends of the night elves, prowl the vale in numbers, among them a brute called Carnivous the Breaker. Sentinel Tysha Moonblade keeps a lonely post by the road. Farther south, near the border, a Sentinel carrying word to Auberdine was ambushed and poisoned by furbolg trackers.', 'warcraft.wiki.gg/wiki/Twilight_Vale (southern forest from south of Ameth''Aran to the Ashenvale border, corrupted furbolgs, rabid bears, stay on the roads; BfA content ignored); warcraft.wiki.gg/wiki/Darkshore_(Classic) (Wildbend River listed under Twilight Vale; furbolgs once friendly); quest 986 description (moonstalkers near Wildbend River); quest 5713 description (Aynasha ambushed and poisoned by furbolg trackers); DB area 2077: thistle bears, moonstalkers, foreststriders, Sickly Deer, Blackwood tribe, Carnivous the Breaker 2186, Sentinel Tysha Moonblade 3639, Sentinel Aynasha 11711; area 454 has the same wildlife'),
(14811, 1, 148, 11, 0, 0, 'Grove of the Ancients', 'Nestled against the mountains due south of Auberdine, the Grove of the Ancients is a sacred place built among the ruins of an old night elf temple. Here dwells Onu, an Ancient of Lore, patient and wise. The night elves of Auberdine count the Ancients as venerable allies and heed their warnings. Onu had long awaited a message from the Arch Druid in Darnassus, and he keeps a wary eye on the Twilight''s Hammer at the Master''s Glaive to the south. Two merchants keep a small camp in the grove, and Kerlonian Evershade, a Druid of the Claw still drowsy from the Emerald Dream, has stopped here for a nap.', 'warcraft.wiki.gg/wiki/Grove_of_the_Ancients (sacred ruin of an old night elven temple, Onu, two merchants and a sleeping druid); quest 952 description (due south of Auberdine; Onu awaiting word); quest 948 description (patient and wise); quest 947 description (venerable allies, warnings); quest 953 completion text (inform the Circle of Ancients); quest 5321 description (Kerlonian); DB area 448: Onu 3616, Ullanna 4194, Tiyani 4195, Kerlonian Evershade 11218'),
(14812, 1, 148, 12, 0, 0, 'Blackwood Den', 'Blackwood Den is a cave of the Blackwood furbolgs in southern Darkshore, south of Auberdine and a short way off the road. Ursa and shamans of the tribe hold it, and they have no welcome for strangers. Volcor, master of the bear Grimclaw, was wounded by the furbolgs and trapped inside, unable to win his way out alone. Grimclaw went north to Auberdine for help, and afterwards waited by the roadside to show a rescuer the way to his master. Getting out again meant fighting a path down to the road, or slipping past the furbolgs unseen.', 'quest 993 description (cave south of Auberdine, Grimclaw waits by the road); quest 993 reward text (furbolgs wounded Volcor); quests 994, 995 descriptions; creature_text 3695 (Grimclaw rousing Terenthis); DB area 455: Blackwood Ursa 2170, Blackwood Shaman 2171, Volcor 3692'),
(14813, 1, 148, 13, 0, 0, 'The Master''s Glaive', 'In the south of Darkshore a vast blade stands driven into the earth. This is the Master''s Glaive, marking the place where one of the old lords of the earth, defeated long ago, was impaled and fell. The lord is long dead, but Onu fears that slivers of its power remain, and the Twilight''s Hammer, who worship such ancient masters, have come for them. Thugs and disciples of the cult camp at the site now, crying glory and blood for the Old Gods, a firecaller named Radison among them, and in their camp lies a maddening tome written in an ancient elven tongue. A wanderer named Therylune strayed too close and found herself surrounded.', 'quest 944 description and reward text (old lord impaled by the glaive, slivers of power, cult worships old lords of the earth); warcraft.wiki.gg/wiki/Master''s_Glaive (sword embedded in a fallen Old God servant; Twilight''s Hammer excavating); creature_text 2338/2339 (Glory and blood for the Old Gods); quests 949, 950, 951 (Twilight Tome, elven text); quest 945 description (Therylune surrounded); DB area 449: Twilight Thug, Twilight Disciple, Firecaller Radison 2192, Therylune 3584, Twilight Tome 12666; quest 961 reward text (Twilight''s Hammer cultists); creature_text 2338/2339 (the Hammer will still fall)'),
(14814, 1, 148, 14, 0, 0, 'Remtravel''s Excavation', 'In southwestern Darkshore, near the coast, the Explorers'' League opened a dig under Prospector Remtravel, famed at the academy in Ironforge for his discoveries. The dwarves uncovered evidence of a great society, and then horrible golems sprang from the ground and overran the site. Cracked golems and stone behemoths still lumber among the tents. His assistant Hollee fled to Auberdine for help. Remtravel, oblivious as ever, stayed behind, chiseling at the stone and hunting for his stone brush and for a mysterious fossil he had promised to send the League.', 'quest 729 description and reward text; quest 730 log description (dwarven excavation team); warcraft.wiki.gg/wiki/Remtravel''s_Excavation (dig site, fossil, golems); DB area 450: Cracked Golem 2156, Stone Behemoth 2157, Prospector Remtravel 2917'),
(14815, 1, 148, 15, 0, 0, 'Twilight Shore', 'The Twilight Shore is the long southern coast of Darkshore, running from west of Ameth''Aran down to the Ashenvale border. Greymist murlocs have built hutted camps along the sand. One of them is the haunt of Murkdeep, for whose death the Auberdine Village Council has offered a reward, and another murloc, Flagglemurk the Cruel, prowls the beaches farther north. Near the border, naga of Blackfathom and Fallenroot satyrs lurk at the water''s edge, kin to those in the drowned ruins on the Ashenvale coast. The fisherman Heldan Galesong casts his line here all the same.', 'DB area 2078: Greymist murlocs, Murkdeep 10323 (map 35.7,76.7), Flagglemurk the Cruel 7015 (36.7,67.6), Blackfathom Oracle/Tide Priestess and Fallenroot Satyr/Rogue (around 31-32,93), Heldan Galesong 4307 (37.0,56.3); quest 4740 description (hutted murloc camp south of Auberdine, Village Council bounty); quest 1275 description (satyr and naga in Blackfathom Deeps on the Ashenvale coast)'),
(14816, 2, 148, 1, 1, 0, 'Thundris Windweaver', 'Thundris Windweaver serves as elder of Auberdine, offering sage and just stewardship of the village''s daily affairs. He sees the dangers plainly: dark forces at the borders, ancient taints resurfacing and new evils rising to topple the balance of the land. He wants the Highborne implements of Ameth''Aran destroyed so the horrors of the past are not repeated, and he traced the fouling of the Cliffspring River to Felwood. His friendships reach far. Through his old friend Huntress Kella Nightbow came a letter from the draenei of Blood Watch proposing an alliance, and he recognized among the draenei''s foes some ancient enemies of his people. Raene Wolfrunner insists she once saved his life.', 'quest 4761 description (elder, sage and just stewardship); npc_text 50024 (gossip); quest 958 description and completion text; quest 4762 reward text; quest 9633 description and reward text (Kella''s old friend, letter from Paetheus); quest 9632 description (Blood Watch proposes cooperation); quest 10752 reward text (Raene pulled him from harm''s way); creature_queststarter 3649 (Thundris gives 10752)'),
(14817, 2, 148, 2, 1, 0, 'Onu', 'Onu is an Ancient of Lore who dwells in the Grove of the Ancients, patient, wise and sparing with his words. The wind whispers to those who listen, he says, and he listens. He had long awaited word from Arch Druid Fandral Staghelm, and when the message finally came he remarked mildly that the Arch Druid always seems in such a hurry, when the forest knows that all shall come to pass in its appointed time, as Shan''do Stormrage understood. Onu finds it strange that naga have come to Darkshore, and stranger still the Twilight''s Hammer. He speaks to those who help him through scrying bowls and weighs what they bring in long meditation.', 'npc_text 50025 (gossip); quest 952 description and reward text; quest 948 description (patient and wise); quest 944 description (naga, Twilight''s Hammer, scrying bowl); quest 961 reward text and creature_text 3616 (meditation); warcraft.wiki.gg/wiki/Onu (pre-Cataclysm)'),
(14818, 2, 148, 3, 1, 0, 'Terenthis', 'Terenthis, a druid, has come to Auberdine to learn how far the fel moss has spread through Darkshore, for the corruption of Teldrassil and the lands around it troubles the druids of the Cenarion Circle and all night elves. Some of his brethren were rescued from a corrupt furbolg on Teldrassil, and he has vowed to stop such atrocities before more of his kind are hurt or worse. He began with the Blackwood furbolgs, and what he found confirmed his fears. He takes no pleasure in killing the creatures of the forest, but with no cure yet found he believes the corruption must be held back. When the bear Grimclaw came roaring into town, a spell let Terenthis understand him.', 'npc_text 3334 (gossip); quest 984 description; quest 985 reward and completion text; creature_text 3693 and 3695 (Grimclaw scene); creature_text 3695 group 2 (the druid seems to understand the bear)'),
(14819, 2, 148, 4, 1, 0, 'Asterion', 'Asterion was second to Athrikus Narassin when the Highborne governed the twin towns of Ameth''Aran and Bashal''Aran, a mage known for his physical prowess as much as his arcane art, who lived among the people of Bashal''Aran and saw to their needs. Athrikus imprisoned him with a moonstone seal, and when his long life ended he found himself still captive, a specter caged by the pillars of a shrine. For a thousand years and more he has stared at them. His courtesy has grown dry and barbed, and he fears his mind may never recover. Freed at last, he recalls a world where the Well still stood and Azshara held court, and he senses that his old master yet lives.', 'page_text 364, 365 (The Lay of Ameth''Aran); quest 954 reward text; quests 955, 956 descriptions and completion texts; quest 957 reward text (Athrikus his jailor, former master); warcraft.wiki.gg/wiki/Bashal''Aran (Narassin used a moonstone seal to imprison Asterion; still imprisoned after death)'),
(14820, 2, 148, 5, 0, 0, 'Athrikus Narassin', 'Athrikus Narassin was a favorite of Queen Azshara, set over the twin towns of Ameth''Aran and Bashal''Aran, though he preferred the solitude of his Tower of Althalaxx to the people he ruled. When the Sundering came and Ameth''Aran lay in ruins, he appeared among its terrified people with a promise: by his spell they would have life eternal, while all around them perished. Highborne souls have been trapped in his soul gems ever since, feeding his power. He bound his own second, Asterion, with a moonstone seal. Ten thousand years on, this ancient and powerful warlock leads the Cult of the Dark Strand from the top of his tower, ringed by his strongest followers.', 'page_text 364, 366, 367 (favored of Azshara, governor, tower, the spell of life eternal); quest 1140 description and reward text (soul gems with trapped Highborne souls, his power); creature_text 3663 (other soulgems, to undo his magic); quest 957 reward text (jailor of Asterion); quest 1143 description and completion text (top of the tower, ancient and powerful warlock); quest 981 description and creature_template subname (Cult of the Dark Strand); warcraft.wiki.gg/wiki/Darkshore (Athrikus trapped his people''s souls in soul gems)'),
(14821, 2, 148, 6, 1, 0, 'Cerellean Whiteclaw', 'Cerellean Whiteclaw loved Anaya Dawnrunner of Ameth''Aran in the age when the Well of Eternity still stood. After the battles at the Well of Eternity he heard that her town had been destroyed and its people killed, Anaya among them, and in his grief he followed Shan''do Stormrage into the long sleep, taking his sorrow into his dreams through the passing of the ages. Thousands of years later her memory still haunted him. Wandering the woods of Darkshore in a daze, he came upon the ruins and saw her spirit there, haunted and restless. He knew she must be freed but could not raise his hand against her. When she was released at last, her final words were for him.', 'quest 963 description, reward and completion text; creature_text 3644 (lines to Anaya); creature_text 3667 (Finally, my soul may rest... Oh, dearest Cerellean)'),
(14822, 2, 148, 7, 1, 0, 'Prospector Remtravel', 'Prospector Remtravel of the Explorers'' League is a legend at the academy in Ironforge for his great discoveries, and a trial to anyone who works beside him. Chief Archaeologist Greywhisker assigned Hollee to work under him in Darkshore, and their dig soon turned up evidence of a great society. When golems burst from the earth and overran the site, Hollee ran for help, while Remtravel never seemed to notice. He mistakes strangers for Hollee, loses his stone brush and the fossil he promised the League, stops to admire his copy of Green Hills of Stranglethorn, and pauses mid fight to inspect a mossy stone. Hollee despairs of him.', 'quest 729 description and reward text; quest 731 description and reward text; creature_text 2917 (escort lines)'),
(14823, 2, 148, 8, 1, 0, 'Volcor and Grimclaw', 'Volcor travels the Darkshore woods with his bear Grimclaw, and can take a beast''s shape himself when he needs to run. The Blackwood furbolgs wounded him in the south and cornered him in a cave, too hurt to break out alone. Grimclaw went for help, bursting into Auberdine and roaring and stamping at Terenthis until he was understood. Terenthis sewed a cloak of moonstalker pelts enchanted so that the wearer could pass Darkshore''s creatures unhindered, and a rescuer wrapped in it found the bear waiting by the road. Grimclaw led the way, and at the sight of his master he rushed forward and licked his face. The two then escaped together, by force or by stealth.', 'quests 986, 993, 994, 995 descriptions and reward texts; creature_text 3692 (Volcor, form shifts); creature_text 3695 and 3693 (Grimclaw and Terenthis)'),
(14824, 2, 148, 9, 1, 0, 'Wizbang Cranktoggle', 'Wizbang Cranktoggle is a gnome inventor living in Auberdine, proud of his newest creation, the buzzbox, a box with levers that lets people talk across great distances. He has set several around Darkshore, each placed near the creatures whose parts will fix its particular fault, and each, he claims, in constant need of repair. As each box hums back to life his voice through it grows more slurred, broken by hiccups and loud gulping. The truth comes out at last. The buzzboxes also brew and distill fine liquor, a trade the night elves do not appreciate in their towns, and Wizbang happily sings the praises of crawler wine, thresher ale and moonstalker moonshine.', 'quests 983, 1001, 1002, 1003 descriptions, reward and completion texts; creature_template 3666 faction 64 (Gnomeregan Exiles)'),
(14825, 2, 148, 10, 0, 0, 'Murkdeep', 'Murkdeep is a murloc with a price on his head. The Auberdine Village Council holds him responsible for the death of at least one Sentinel and suspects him of sinking at least two cargo vessels in the waters off Darkshore. He was last seen at a hutted murloc camp on the shore south of the town, thought to be guarding its huts. He keeps out of sight there until the camp''s warriors and hunters have fallen, then comes out to fight. The bounty is to be claimed from Sentinel Glynda Nal''Shea, who promises that the townsfolk will sleep a little more soundly and safely once he is dead.', 'quest 4740 description and reward text; DB: Murkdeep 10323 spawned at map 35.7,76.7 in Twilight Shore (guid 1976190, not an event spawn); src/server/scripts/Kalimdor/zone_darkshore.cpp npc_murkdeep (hidden until the camp''s Greymist Warriors and Hunters are dead and a player is near; summons waves; no quest or faction check)'),
(14826, 3, 148, 1, 1, 0, 'The Twilight''s Hammer at the Master''s Glaive', 'It began with mushrooms. Barithras Moonshade of Auberdine needed rare fungi from the cave behind Cliffspring Falls, but the Ancients had warned him away, sensing that a new evil hid there. Whoever gathered them saw what lurked inside, and soon Onu himself asked to speak with them. Onu thought it strange that naga had come to Darkshore, but stranger still the Twilight''s Hammer, a cult that worships old lords of the earth defeated long ago. One such lord fell at the Master''s Glaive, and Onu sent his visitor there with a phial of scrying, to speak with him through a bowl. The cultists were indeed at the Glaive, seeking the slivers of power the dead lord left behind. In their camp lay a tome of maddening script, and the one page that could be torn from it proved to come from an ancient elven text: the cult was using elven magic to bring its masters back. Onu then sent for relics from the Ruins of Mathystra, hoping to unlock that magic before his enemies could.', 'quests 947, 948, 944, 949, 950, 951 descriptions and reward texts; creature_text 3583 (Barithras); quest 961 reward text (Onu: the finding of Twilight''s Hammer cultists is troubling); quest_template_addon PrevQuestID chain 947 > 948 > 944 > 949 > 950 > 951'),
(14827, 3, 148, 2, 1, 0, 'The Absent Minded Prospector', 'Archaeologist Hollee had been proud to be assigned to the famous Prospector Remtravel, and the dig in southern Darkshore had gone well, turning up evidence of a great society. Then horrible golems sprang from the ground and overran the site. Hollee ran to Auberdine for help, while Remtravel stayed behind, apparently never noticing the danger. When her plea was answered, the prospector was found still at his stones, mistaking his visitor for Hollee and fretting over a lost stone brush and a mysterious fossil he had promised the Explorers'' League. Searching for it meant guarding him through the ruined camp while golems and beasts came at him from every side, and as he wandered from tent to stone he finally remembered that he had given the fossil to Hollee all along. Hollee would not leave Darkshore without him, so the fossil was carried to the League in Darnassus, and from there its trail led on across the sea to Menethil Harbor.', 'quest 730 description; quests 729, 731, 741, 942 descriptions and reward texts; creature_text 2917 (escort, fossil given to Hollee); Wetlands entry 1131 The Whelgar Excavation (943 onward)'),
(14828, 3, 148, 3, 1, 0, 'The Blackwood Corrupted', 'Terenthis began his inquiry into Darkshore''s corruption with the furbolgs, and the Blackwood camp south of Auberdine showed it plainly. With the tribe so close to the town he asked for its pathfinders and windtalkers to be thinned, grieving the need, since no cure had been found for the fel moss loose in the forest. His findings went to Thundris Windweaver, who suspected the Blackwood were not the true root of the evil. The Cliffspring River, fouling near the tribe''s northern camp, pointed east to Felwood, and in time it emerged that satyrs held the furbolgs in thrall through talismans that channel their magic. A bowl of moonwell water mixed with the tribe''s own fruit, nuts and grain, set by the bonfire at the river camp, cleansed the furbolgs who ate just long enough to draw out the satyr corruptor, Xabraxxis. His Talisman of Corruption came back to Auberdine: one battle won in the war to reclaim the forest, and some hope that the Blackwood may yet be freed.', 'quests 984, 985, 4761, 4762, 4763 descriptions and reward texts; event_scripts 3938 (summons Xabraxxis 10373 at the northern camp); gameobject_loot_template 14500 (Xabraxxis'' Demon Bag holds the Talisman of Corruption); warcraft.wiki.gg/wiki/Blackwood_tribe (corrupted by satyr interlopers led by Xabraxxis)'),
(14829, 3, 148, 4, 1, 0, 'The Fall of Ameth''Aran', 'Sentinel Tysha Moonblade was sent to explore Ameth''Aran and found two great tablets, but the Highborne spirits fell on her as she read them and she fled. Their words, once deciphered, give the Circle of Ancients a rare record of the War of the Ancients. The Lay of Ameth''Aran tells how the children of the stars built their homes on the shores of the Well, where Elune was said to rest, and how Azshara set Athrikus Narassin over the twin towns, with Asterion as his second. The Fall tells of ancient trees uprooted, a sky torn by magic and brother fighting brother. As Ameth''Aran lay in ruins, Athrikus appeared and promised its people, with a spell, life eternal. In Auberdine, Thundris Windweaver wants the magical implements their restless spirits still wield taken and destroyed, so that their long dormant evil is never released again.', 'quest 953 description and reward text; page_text 358, 364, 365 (The Lay of Ameth''Aran); page_text 359, 366, 367 (The Fall of Ameth''Aran); quest 958 description and reward text'),
(14830, 3, 148, 5, 1, 0, 'The Prisoner of Bashal''Aran', 'Thundris Windweaver had noticed that the demons infesting Bashal''Aran shunned one shrine, a small bluff on its western side bathed in a strange blue aura. Within waited Asterion, a Highborne specter whose dry courtesy could not hide centuries of torment. A seal held him there, and he asked for help finding it. The earrings worn by the grells carried a trace of it, enough to show that the seal had passed to the satyrs who led them, and from a Deth''ryll satyr came the Ancient Moonstone Seal itself, the work of one of the mightiest of the Highborne. It could be unmade only in the ancient blue flame that still burns in Ameth''Aran, twin of his town. When the seal was destroyed, Asterion was free for the first time since the Well of Eternity stood. He named his jailor, his former master Athrikus, sensed that he still lived, and felt his despair give way to thoughts of vengeance.', 'quests 954, 955, 956, 957 descriptions, reward and completion texts; creature_loot_template: Ancient Moonstone Seal 5338 from Deth''ryll Satyr 2212; Grell Earring 5336 from Wild Grell 2190 and Vile Sprite 2189'),
(14831, 3, 148, 6, 1, 0, 'The Tower of Althalaxx', 'Sentinel Elissa Starbreeze, charged with keeping Auberdine from harm, had sent Balthule Shadowstrike to watch the strange happenings at the Tower of Althalaxx, and when he was long overdue she sent someone to find him. He had stayed at his post, afraid to miss something. Warlocks had gathered around and inside the tower, and parchments taken from them gave the company a name, the Cult of the Dark Strand, though Balthule knew nothing of its history. His master Delgren the Purifier, a paladin who helps the Sentinels against demons and undead, had suspected such a gathering, and Balthule''s letter went south to him in Ashenvale, where the hunt for the cult''s power carried on. When it was done, Balthule had news of his own: a blinding flash from the upper room of the tower, then screams and lightning striking the ground. The time had come. Athrikus Narassin fell at the top of his tower, and word went south to Delgren that the Cult of the Dark Strand was beaten and scattered.', 'quests 965, 966, 967, 1167, 1143, 981 descriptions and reward texts; quest_template_addon PrevQuestID chain and creature_queststarter/questender (Delgren 3663 in Ashenvale ends 967 and 981, gives 970, 973, 1140, 1167); page_text 361, 437 (Balthule''s letter to Delgren)'),
(14832, 3, 148, 7, 1, 0, 'Tharnariun''s Hope', 'A sickness has spread across Darkshore, gripping the minds and bodies of all it touches, and the thistle bears have suffered worst, once noble beasts made rabid and frenzied. Tharnariun Treetender of Auberdine hoped he had a cure. A trap of light laid in the forest calmed a rabid bear long enough to be led back to him, but the cure failed. With sorrow he ordered the sick bears put down, knowing it would only slow the plague''s damage for a time, and at last sent his helper to a cave near Bashal''Aran to slay the infected Den Mother, from whom ever more rabid bears were spreading into the land. He gave thanks for those who answered his call, for in these war torn lands, he said, many choose to hide in their homes or flee to the safer lands of the Alliance.', 'quests 2118, 2138, 2139 descriptions, reward and completion texts; DB: Den Mother 6788 at map 51.5,38.3'),
(14833, 3, 148, 8, 1, 0, 'Washed Ashore', 'Great creatures of the sea have long been known to fling themselves onto the Darkshore coast and die there, but lately they have been washing ashore in ever greater numbers. The Temple of the Moon sent Gwennyth Bly''Leggonde to Auberdine to learn why. Greymist murlocs made her work hard, ringing a giant carcass on the beach south of the town, so she asked for help gathering its bones to send by hippogryph to Darnassus. A second find, the remains of a sea turtle in the water west of Auberdine near a sunken vessel, gave her a real chance at the mystery, and she asks to hear of any other beached creatures along the coast. The idea that troubles her most is that the creatures may be fleeing the waters around Teldrassil. She cannot help thinking the strandings are an ill omen.', 'quest 3524 description, reward and completion text; quest 4681 description and reward text; npc_text 5943 (Gwennyth gossip)'),
(14834, 3, 148, 9, 1, 0, 'The Red Crystal', 'The moonkin of Darkshore were once thought gentle, almost mystical creatures, and some still revere them, but Sentinel Glynda Nal''Shea must keep Auberdine safe, and hostile moonkin now roam east of the town in growing numbers. Reports claimed they were being drawn to a large red crystal along the eastern mountains, though no one knew whether it even existed. It does. Glynda, who suspects it is tied to Felwood above, had moonwell water poured over it, and its opaque surface turned clear to reveal small fragments of bone and half a jawbone, seemingly a humanoid''s, locked inside a stone that even strong magic could hardly break. The answers raised only more questions. Glynda took them to the town council, content for now that the threat lay far enough to the east.', 'quests 4811, 4812, 4813 descriptions and reward texts; DB: Mysterious Red Crystal 175524, moonkin spawns around map 43-46,48-50');
